mapper.select:
SELECT p.id, p.paper_name AS paperName, p.paper_type AS paperType, p.total_score AS totalScore, p.pass_score AS passScore, p.duration, u.real_name AS creatorName, (SELECT COUNT(*) FROM paper_question pq WHERE pq.paper_id = p.id) AS questionCount, p.create_time AS createTime, p.update_time AS updateTime FROM paper p LEFT JOIN user u ON p.creator_id = u.id
AND p.creator_id = #{creatorId}
ORDER BY p.create_time DESC
